function showView(v){
  document.querySelectorAll(".view").forEach(el=>el.classList.remove("active","fade-in"));
  const t=document.getElementById("view-"+v);
  if(!t)return;
  t.classList.add("active");
  requestAnimationFrame(()=>t.classList.add("fade-in"));
  document.querySelectorAll(".s-link").forEach(l=>l.classList.toggle("active",l.dataset.view===v&&!l.dataset.cat));
  window.scrollTo({top:0,behavior:"smooth"});
  closeSidebar();
  if(VIEW_TITLES[v]) document.title = VIEW_TITLES[v];
  if(v==="schools")renderSchools();
  if(v==="careers")renderCareers();
  if(v==="cost")calcCost();
  if(v==="scholarship")renderScholarships();
  if(v==="facts")renderHomeVoices();
  if(v==="home"){
    typeHero();
    if(window.__layoutHero3D)window.__layoutHero3D();
  }
  try{sessionStorage.setItem("tv_view",v);}catch(e){}
  const onSharedUrl=/[#&](plan|cost)=/.test(location.hash)||/[?&](plan|cost)=/.test(location.search);
  if(v==="home"){
    if(!onSharedUrl&&location.pathname!=="/"&&history.replaceState){
      history.replaceState(null,"","/");
    }
  }else if(!onSharedUrl&&!v.endsWith("-detail")){
    if(history.replaceState)history.replaceState(null,"","/"+v);
  }
}
document.querySelectorAll("[data-view]").forEach(el=>{
  el.addEventListener("click",()=>{
    const v=el.dataset.view;
    const cat=el.dataset.cat;
    showView(v);
    if(v==="schools"&&cat){filterSchoolsByCat(cat);}
  });
});
document.querySelector('.s-link[data-view="home"]').classList.add("active");

/* ===== BAC II GUIDANCE TABS ===== */
function switchBaciiTab(tabId){
  document.querySelectorAll("#bacii-tabs .chip").forEach(c=>{
    c.classList.toggle("active", c.dataset.bacii===tabId);
  });
  document.querySelectorAll(".bacii-panel").forEach(p=>{
    const match = p.id === "bacii-panel-" + tabId;
    p.hidden = !match;
    p.classList.toggle("active", match);
  });
}
window.switchBaciiTab = switchBaciiTab;

