/* ===== CUSTOM DROPDOWN (styled select that syncs with native <select>) ===== */
function enhanceSelect(sel){
  if(sel.dataset.cs)return;sel.dataset.cs="1";
  const isForm=sel.classList.contains("form-input");
  const wrap=document.createElement("div");
  wrap.className="cs-wrap"+(isForm?" full":"");
  sel.parentNode.insertBefore(wrap,sel);
  wrap.appendChild(sel);
  sel.classList.add("cs-native");
  const trigger=document.createElement("button");
  trigger.type="button";
  trigger.className="cs-trigger "+(isForm?"cs-form":"cs-filter");
  trigger.innerHTML='<span class="cs-label"></span><i class="material-symbols-outlined cs-arrow">expand_more</i>';
  const panel=document.createElement("div");panel.className="cs-panel";
  const label=trigger.querySelector(".cs-label");
  // An <option data-icon="..."> renders a Material Symbols icon alongside its label —
  // a real <select> can't show icons in its native list, but this custom panel can.
  function optIcon(o){return o.dataset.icon?'<i class="material-symbols-outlined cs-opt-icon">'+o.dataset.icon+'</i>':'';}
  function build(){
    panel.innerHTML=Array.from(sel.options).map((o,i)=>`<div class="cs-option${i===sel.selectedIndex?" sel":""}" data-i="${i}">${optIcon(o)}<span class="cs-label-text">${o.textContent}</span><i class="material-symbols-outlined cs-check">check</i></div>`).join("");
    panel.querySelectorAll(".cs-option").forEach(el=>el.addEventListener("click",()=>{
      const i=+el.dataset.i;
      if(i!==sel.selectedIndex){sel.selectedIndex=i;sel.dispatchEvent(new Event("change",{bubbles:true}));}
      sync();closeAllSelects();
    }));
  }
  function sync(){const o=sel.options[sel.selectedIndex];label.innerHTML=o?optIcon(o)+'<span class="cs-label-text">'+o.textContent+'</span>':"";Array.from(panel.querySelectorAll(".cs-option")).forEach((el,i)=>el.classList.toggle("sel",i===sel.selectedIndex));}
  sel._csSync=sync;
  trigger.addEventListener("click",e=>{e.stopPropagation();const open=wrap.classList.contains("cs-open");closeAllSelects();if(!open){build();sync();wrap.classList.add("cs-open");}});
  /* The real <select> stays in the tab order (visually hidden, not display:none) so
     screen readers and keyboard-only users can operate it directly with full native
     select behavior. Two gaps that leaves for a sighted keyboard user: the visible
     trigger's label didn't update when they changed the hidden select directly
     (only clicks on the custom panel called sync()), and focus landing on the
     invisible select was invisible on screen. */
  sel.addEventListener("change",sync);
  sel.addEventListener("focus",()=>wrap.classList.add("cs-native-focus"));
  sel.addEventListener("blur",()=>wrap.classList.remove("cs-native-focus"));
  wrap.appendChild(trigger);wrap.appendChild(panel);
  build();sync();
}
function closeAllSelects(){document.querySelectorAll(".cs-wrap.cs-open").forEach(w=>w.classList.remove("cs-open"));}
document.addEventListener("click",e=>{if(!e.target.closest(".cs-wrap"))closeAllSelects();});
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeAllSelects();});
/* Activate role="button" cards (school-card/job-card/hc-card) with Enter/Space,
   same as a native <button> -- these can't be real <button>s because they contain
   nested interactive children (compare/save buttons) or heading elements. */
document.addEventListener("keydown",e=>{
  if(e.key!=="Enter"&&e.key!==" ")return;
  const el=e.target.closest('[role="button"]');
  if(!el||e.target!==el)return;
  e.preventDefault();
  el.click();
});
function enhanceAllSelects(){document.querySelectorAll("select.form-input,select.filter-select").forEach(enhanceSelect);}

