function parseRouteFromUrl(){
  // Legacy hash links (#careers, #school=id, #career=id) — kept working for any
  // previously shared/bookmarked URLs from before the switch to clean paths.
  const rawHash=(location.hash||"").replace(/^#/,"").trim();
  if(rawHash){
    if(rawHash.startsWith("school="))return {view:"school-detail",type:"school",id:rawHash.slice(7)};
    if(rawHash.startsWith("career="))return {view:"career-detail",type:"career",id:rawHash.slice(7)};
    const cleanHash=rawHash.replace(/\?.*$/,"").toLowerCase();
    if(cleanHash==="scholarships")return {view:"scholarship"};
    if(document.getElementById("view-"+cleanHash))return {view:cleanHash};
  }

  // Clean path routing: /careers, /schools, /school/<id>, /career/<id>, ...
  const seg=location.pathname.replace(/^\/+|\/+$/g,"").split("/").filter(Boolean);
  if(seg.length){
    const first=seg[0].toLowerCase();
    if(first==="school"&&seg[1])return {view:"school-detail",type:"school",id:decodeURIComponent(seg[1])};
    if(first==="career"&&seg[1])return {view:"career-detail",type:"career",id:decodeURIComponent(seg[1])};
    if(first==="scholarships")return {view:"scholarship"};
    if(document.getElementById("view-"+first))return {view:first};
  }

  // Query-param fallback (?view=, ?school=, ?career=)
  try{
    const params=new URLSearchParams(location.search);
    const qv=params.get("view");
    if(qv&&document.getElementById("view-"+qv))return {view:qv};
    const qs=params.get("school");
    if(qs)return {view:"school-detail",type:"school",id:qs};
    const qc=params.get("career");
    if(qc)return {view:"career-detail",type:"career",id:qc};
  }catch(e){}
  return null;
}

function restoreView(){
  const route=parseRouteFromUrl();
  if(route){
    if(route.view==="school-detail"&&route.id&&typeof openSchool==="function"){openSchool(route.id);return;}
    if(route.view==="career-detail"&&route.id&&typeof openCareer==="function"){openCareer(route.id);return;}
    if(route.view==="schools")restoreSchoolState();
    if(route.view==="careers")restoreJobState();
    if(document.getElementById("view-"+route.view)){showView(route.view);return;}
  }
  let v=null;try{v=sessionStorage.getItem("tv_view");}catch(e){}
  if(!v||v==="home"||v==="shared")return;
  if(v==="school-detail"||v==="career-detail"){
    let d=null;try{d=sessionStorage.getItem("tv_detail");}catch(e){}
    if(d){const i=d.indexOf(":"),t=d.slice(0,i),id=d.slice(i+1);
      if(t==="school"&&typeof openSchool==="function"){openSchool(id);return;}
      if(t==="career"&&typeof openCareer==="function"){openCareer(id);return;}
    }
    return;
  }
  if(v==="schools")restoreSchoolState();
  if(v==="careers")restoreJobState();
  if(document.getElementById("view-"+v))showView(v);
}
window.addEventListener("popstate",()=>{
  if(/[#&](plan|cost)=/.test(location.hash)||/[?&](plan|cost)=/.test(location.search))return;
  restoreView();
});

/* ===== ANIMATED GRID BEAMS: light beams traveling along the background grid lines ===== */
function initGridFlow(){
  if(window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;
  let host=document.getElementById("grid-flow");
  if(!host){host=document.createElement("div");host.id="grid-flow";host.className="grid-flow";host.setAttribute("aria-hidden","true");document.body.appendChild(host);}
  function build(){
    const cell=parseInt(getComputedStyle(document.body).getPropertyValue("--grid-cell"))||52;
    const cols=Math.floor(window.innerWidth/cell);
    const vCount=Math.max(3,Math.min(6,Math.floor(cols/4)));
    const pick=(n,max)=>{const s=new Set();let guard=0;while(s.size<Math.min(n,max-1)&&guard++<200)s.add(1+Math.floor(Math.random()*(max-1)));return[...s];};
    host.innerHTML="";
    const frag=document.createDocumentFragment();
    pick(vCount,cols).forEach(c=>{
      const el=document.createElement("span");
      el.className="gline"+(Math.random()<0.5?" up":"");
      el.style.left=(c*cell)+"px";
      el.style.setProperty("--d",(5+Math.random()*4).toFixed(1)+"s");
      el.style.setProperty("--delay",(Math.random()*5).toFixed(1)+"s");
      frag.appendChild(el);
    });
    host.appendChild(frag);
  }
  build();
  let t;window.addEventListener("resize",()=>{clearTimeout(t);t=setTimeout(build,250);});
}

